SELECT DISTINCTROW 1 AS NUMB1, First("Всего") AS NAME1, w.OES AS oes, w.OBL, w.YEAR, Sum(w.NUST) AS NUST, Sum(w.E) AS E, Sum(w.EOTP) AS EOTP, IIf([EOTP]>0,[EUST]/[EOTP]*1000,0) AS EURT, Sum(w.EUST) AS EUST, Sum(w.Q) AS Q, IIf([Q]>0,[TUST]/[Q]*1000,0) AS TURT, Sum(w.TUST) AS TUST, Sum(w.B) AS B, Sum(w.GAZ) AS GAZ, Sum(w.MAZUT) AS MAZUT, Sum(w.TORF) AS TORF, Sum(w.SLAN) AS SLAN, Sum(w.PROCH) AS PROCH, Sum(w.UGOL) AS UGOL, Sum(w.DON) AS DON, Sum(w.PODM) AS PODM, Sum(w.PECH) AS PECH, Sum(w.ARKT) AS ARKT, Sum(w.KUZN) AS KUZN, Sum(w.URAL) AS URAL, Sum(w.BASHK) AS BASHK, Sum(w.EKIB) AS EKIB, Sum(w.KARAG) AS KARAG, Sum(w.KAN) AS KAN, Sum(w.IRKUT) AS IRKUT, Sum(w.HAK) AS HAK, Sum(w.TUV) AS TUV, Sum(w.BUR) AS BUR, Sum(w.CHIT) AS CHIT, Sum(w.YAKUT) AS YAKUT, Sum(w.AMUR) AS AMUR, Sum(w.URG) AS URG, Sum(w.PRIM) AS PRIM, Sum(w.LUCH) AS LUCH, Sum(w.MAG) AS MAG, Sum(w.SAH) AS SAH, Sum(w.QOTR) AS QOTR, Sum(w.EWTP) AS EWTP, Sum(w.NT) AS NT, First(Имена_областей.NAME) AS oblname, First(Имена_ОЭС.name) AS oesname, Sum(d.nazar) AS nazar, Sum(d.ibor) AS ibor, Sum(d.berez) AS berez, Sum(d.per) AS per, Sum(d.gusin) AS gusin, Sum(d.tugn) AS tugn, Sum(d.azey) AS azey, Sum(d.cher) AS cher, Sum(d.vork) AS vork, Sum(d.int) AS [int], Sum(d.sver) AS sver, Sum(d.chel) AS chel, Sum(d.kizel) AS kizel, Sum(d.kuzngd) AS kuzngd, Sum(d.kuznt) AS kuznt, Sum(d.kuznss) AS kuznss, Sum(d.kuznun) AS kuznun
FROM ((([Рабочий(станции)] AS w INNER JOIN Имена_ОЭС ON w.OES=Имена_ОЭС.oes) LEFT JOIN [Рабочий(доп_угли)] AS d ON (w.YEAR=d.YEAR) AND (w.NUMB1120=d.NUMB1120)) INNER JOIN Имена_областей ON w.OBL=Имена_областей.OBL) INNER JOIN Имена_станций ON w.NUMB1120=Имена_станций.NUMB
WHERE (((Имена_станций.MAIN)=0 Or (Имена_станций.MAIN) Is Null) AND ((w.YEAR)>0))
GROUP BY 1, w.OES, w.OBL, w.YEAR;
